## Summary
When `page.setRequestInterception(true)` is enabled, calling `req.continue({ headers, url, method, postData })` from a `page.on('request', ...)` listener has **no effect** for any intercepted request — including the top-level navigation request itself. All four override fields are silently dropped, and the request goes out unmodified.

### Obscura version or commit

70062e0

### OS and architecture

Windows 11 x64

### How are you using obscura?

CDP server with Puppeteer or Playwright

### Stealth mode

Reproduces with both stealth and non-stealth

### Reproduction
```javascript
const puppeteer = require("puppeteer-core");

const CDP_WS = "ws://127.0.0.1:9222/devtools/browser";
const ECHO = "https://postman-echo.com";

async function runTest(browser, label, path, makeOverride, check) {
  const page = await browser.newPage();
  await page.setRequestInterception(true);
  page.on("request", (req) => {
    if (req.url().includes(path)) {
      req.continue(makeOverride(req));
    } else {
      req.continue();
    }
  });

  let passed = false;
  let detail = "";
  try {
    await page.goto(`${ECHO}${path}`, { waitUntil: "domcontentloaded" });
    const body = await page.content();
    passed = check(body);
    if (!passed) detail = body.slice(0, 200);
  } catch (e) {
    detail = e.message;
  } finally {
    await page.close();
  }

  console.log(`${passed ? "✅PASS" : "❌FAIL"}  [${label}]`);
  return passed;
}

async function main() {
  const browser = await puppeteer.connect({ browserWSEndpoint: CDP_WS });
  const results = [];

  // 1. headers — add x-obscura-test, /headers echoes request headers as JSON.
  results.push(await runTest(
    browser,
    "headers",
    "/headers",
    (req) => ({ headers: { ...req.headers(), "x-obscura-test": "1" } }),
    (b) => b.includes('"x-obscura-test"'),
  ));

  // 2. url — rewrite /fakeurl (would 404) to /get, response should be the
  //    /get echo with url: https://postman-echo.com/get.
  results.push(await runTest(
    browser,
    "url",
    "/fakeurl",
    () => ({ url: `${ECHO}/get` }),
    (b) => b.includes('"url":"https://postman-echo.com/get"'),
  ));

  // 3. method — rewrite a GET navigation to POST and retarget to /post.
  //    /post 404s GET and PUT, only 200s POST, and its echo JSON does NOT
  //    include a "method" field — so we verify the override by checking the
  //    echo body's signature instead.
  results.push(await runTest(
    browser,
    "method",
    "/override-method",
    () => ({ url: `${ECHO}/post`, method: "POST" }),
    (b) => b.includes('"url":"https://postman-echo.com/post"') && b.includes('"form"'),
  ));

  // 4. postData — rewrite to POST /post with a fresh JSON body; /post echoes
  //    the parsed body back as { data: {...} }.
  results.push(await runTest(
    browser,
    "postData",
    "/override-postdata",
    (req) => ({
      url: `${ECHO}/post`,
      method: "POST",
      postData: JSON.stringify({ overridden: true }),
      headers: { ...req.headers(), "content-type": "application/json" },
    }),
    (b) => b.includes('"overridden":true') || b.includes('"overridden": true'),
  ));

  console.log(`\n${results.filter(Boolean).length}/${results.length} passed`);
  await browser.disconnect();
  process.exit(results.every(Boolean) ? 0 : 1);
}

